begin;
update public.organizations set status='active',is_public=true,is_test=false,updated_at=now()where id='72676163-6164-456d-9961-636164656d79'or lower(coalesce(name,''))in('the rudy gay academy','rudy gay academy');
create or replace function public.public_org_profiles()returns table(id uuid,name text,sport text,general_location text,description text,profile_image_url text,accepting_join_requests boolean,team_count bigint,active_program_count bigint,active_program_names text[],request_status text)language sql stable security definer set search_path=public as $$ select o.id,coalesce(nullif(os.org_name,''),nullif(o.name,''),'Organization'),os.sport,os.general_location,os.description,os.profile_image_url,coalesce(o.accepting_join_requests,false),(select count(*)from org_teams t where t.org_id=o.id),(select count(*)from programs p where p.org_id=o.id and p.status='active'),(select coalesce(array_agg(p.name order by p.start_date asc nulls last),'{}')from programs p where p.org_id=o.id and p.status='active'),(select jr.status from org_join_requests jr where jr.org_id=o.id and jr.requester_id=auth.uid()order by jr.created_at desc limit 1)from organizations o left join org_settings os on os.org_id=o.id where o.status='active'and o.is_public=true and coalesce(o.is_test,false)=false order by coalesce(nullif(os.org_name,''),nullif(o.name,''),'Organization')$$;
revoke all on function public.public_org_profiles()from public,anon;grant execute on function public.public_org_profiles()to authenticated;notify pgrst,'reload schema';commit;
